-- 100 spell_dbc rows for the '+5% to all stats' bonus per unique boss killed
-- (kill_milestones.cpp, GrantBossBonusIfReached). Each spell is INDEPENDENT
-- (like the tier buffs), one effect: SPELL_AURA_MOD_TOTAL_STAT_PERCENTAGE
-- (137) with EffectMiscValue=-1 (all 5 stats), EffectBasePoints=5. The
-- player accumulates these one at a time (one per new unique boss), so the
-- total bonus at N unique bosses = 5%*N (max 100 bosses = +500%).
-- Attributes=64 = SPELL_ATTR0_PASSIVE (permanent, no buff-bar icon, same
-- trade-off as the other tier buffs).
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 901000 AND 901099;
